<template>
	<view class="diamond-page">
		<view class="balance-panel">
			<text class="balance-label">我的钻石</text>
			<view class="balance-row"><image class="diamond-icon" src="/static/img/zuanshi.png" mode="aspectFit" /><text class="balance">{{ summary.balance }}</text></view>
			<view class="balance-actions">
				<view class="recharge-button" @click="openRecharge">充值钻石</view>
				<view class="task-button" @click="goTasks">做任务赚钻石</view>
			</view>
		</view>
		<view class="records">
			<text class="section-title">最近明细</text>
			<view v-if="!summary.records.length" class="empty">还没有钻石记录</view>
			<view v-for="record in summary.records" :key="record.id" class="record-row">
				<view><text class="record-title">{{ record.description }}</text><text class="record-time">{{ formatTime(record.createdAt) }}</text></view>
				<text class="amount" :class="{ spend: record.amount < 0 }">{{ record.amount > 0 ? '+' : '' }}{{ record.amount }}</text>
			</view>
		</view>

		<view v-if="rechargeVisible" class="recharge-mask" @touchmove.stop.prevent @click="closeRecharge">
			<view class="recharge-sheet" @click.stop>
				<view class="sheet-handle"></view>
				<view class="sheet-head">
					<view><text class="sheet-title">充值钻石</text><text class="sheet-subtitle">{{ summary.isMember ? 'VIP 会员充值，钻石双倍到账' : '充值成功后立即到账' }}</text></view>
					<view class="sheet-close" @click="closeRecharge">×</view>
				</view>
				<view class="vip-double" :class="{ active: summary.isMember }" @click="goMembership">
					<view><text class="vip-double-title">{{ summary.isMember ? 'VIP 双倍权益已生效' : '开通 VIP，充值钻石全部双倍' }}</text><text class="vip-double-sub">{{ summary.isMember ? '本次充值将按页面显示的双倍数量到账' : '同样价格，获得 2 倍钻石' }}</text></view>
					<text v-if="!summary.isMember" class="vip-double-action">去开通</text>
					<text v-else class="vip-double-badge">2X</text>
				</view>
				<scroll-view class="plan-scroll" scroll-x :show-scrollbar="false">
					<view class="plan-grid">
						<view v-for="plan in summary.rechargePlans" :key="plan.type" class="plan-item" :class="{ selected: selectedPlanType === plan.type }" @click="selectedPlanType = plan.type">
							<view v-if="plan.recommended" class="recommend-badge">推荐</view>
							<view v-if="summary.isMember" class="double-tag">VIP 双倍</view>
							<view class="plan-diamonds"><image src="/static/img/zuanshi.png" mode="aspectFit" /><text>{{ plan.creditedDiamonds || plan.diamonds }}</text></view>
							<text v-if="summary.isMember" class="base-diamonds">原 {{ plan.diamonds }} 钻</text>
							<text class="plan-label">{{ plan.label }}</text>
							<text class="plan-price">¥{{ formatPrice(plan.price) }}</text>
						</view>
					</view>
				</scroll-view>
				<view class="pay-button" :class="{ disabled: paying || !selectedPlan }" @click="paySelectedPlan">
					{{ paying ? '正在支付...' : selectedPlan ? `立即支付 ¥${formatPrice(selectedPlan.price)}` : '请选择充值面额' }}
				</view>
				<text class="pay-note">支付即表示同意《充值协议》，钻石为虚拟道具，充值后不可提现</text>
			</view>
		</view>
	</view>
</template>

<script>
import {
	createDiamondOrder,
	DEFAULT_DIAMOND_RECHARGE_PLANS,
	fetchDiamondOrder,
	fetchDiamonds
} from '../../api/diamond';
import { showRequestError } from '../../utils/feedback';

export default {
	data() {
		return {
			summary: { balance: 0, isMember: false, rechargeMultiplier: 1, records: [], rechargePlans: DEFAULT_DIAMOND_RECHARGE_PLANS },
			rechargeVisible: false,
			selectedPlanType: '',
			autoOpenRecharge: false,
			summaryReady: false,
			paying: false
		};
	},
	computed: {
		selectedPlan() {
			return this.summary.rechargePlans.find((plan) => plan.type === this.selectedPlanType) || null;
		}
	},
	onLoad(options = {}) {
		this.autoOpenRecharge = String(options.recharge || '') === '1';
	},
	onShow() { this.loadData(); },
	methods: {
		async loadData() {
			try {
				const result = await fetchDiamonds();
				const rechargePlans = Array.isArray(result && result.rechargePlans) && result.rechargePlans.length
					? result.rechargePlans
					: DEFAULT_DIAMOND_RECHARGE_PLANS;
				this.summary = {
					...result,
					records: Array.isArray(result && result.records) ? result.records : [],
					rechargePlans
				};
				if (!rechargePlans.some((plan) => plan.type === this.selectedPlanType)) {
					const defaultPlan = rechargePlans.find((plan) => plan.recommended) || rechargePlans[0];
					this.selectedPlanType = defaultPlan ? defaultPlan.type : '';
				}
				if (this.autoOpenRecharge && this.summary.rechargePlans.length) {
					this.autoOpenRecharge = false;
					this.rechargeVisible = true;
				}
			} catch (error) {
				showRequestError(error, '钻石信息加载失败');
			} finally {
				this.summaryReady = true;
			}
		},
		async openRecharge() {
			if (!this.summaryReady) await this.loadData();
			this.rechargeVisible = true;
		},
		closeRecharge() {
			if (!this.paying) this.rechargeVisible = false;
		},
		async paySelectedPlan() {
			if (!this.selectedPlan || this.paying) return;
			this.paying = true;
			try {
				const order = await createDiamondOrder(this.selectedPlan.type);
				if (!order || !order.payment) throw new Error('支付参数未返回，请检查支付配置。');
				if (!uni.requestPayment) throw new Error('当前环境不支持微信支付，请使用微信小程序真机。');
				await new Promise((resolve, reject) => {
					uni.requestPayment({ ...order.payment, success: resolve, fail: reject });
				});
				const paid = await this.waitForOrderPaid(order.orderId);
				if (paid) {
					this.rechargeVisible = false;
					await this.loadData();
					uni.showToast({ title: `${paid.creditedDiamonds || order.diamonds}钻石已到账`, icon: 'success' });
				} else {
					this.rechargeVisible = false;
					uni.showModal({ title: '支付结果确认中', content: '支付结果正在同步，稍后返回本页即可查看到账余额。', showCancel: false });
				}
			} catch (error) {
				const message = String((error && (error.errMsg || error.message)) || '');
				if (/cancel/i.test(message)) return;
				if (Number(error && error.statusCode) === 404) {
					uni.showModal({
						title: '充值服务待更新',
						content: '当前线上后端尚未发布钻石充值接口，请更新并重启后端服务后重试。',
						showCancel: false
					});
					return;
				}
				showRequestError(error, '钻石充值失败');
			} finally {
				this.paying = false;
			}
		},
		async waitForOrderPaid(orderId) {
			for (let attempt = 0; attempt < 8; attempt += 1) {
				if (attempt) await new Promise((resolve) => setTimeout(resolve, 800));
				try {
					const order = await fetchDiamondOrder(orderId);
					if (order && order.status === 'paid') return order;
					if (order && order.status === 'failed') return false;
				} catch (error) {
					if (attempt === 7) return false;
				}
			}
			return false;
		},
		goTasks() { uni.navigateTo({ url: '/pages/tasks/index' }); },
		goMembership() {
			if (!this.summary.isMember) uni.navigateTo({ url: '/pages/membership/index' });
		},
		formatPrice(value) { return Number(value || 0).toFixed(2); },
		formatTime(value) {
			const date = new Date(value);
			if (Number.isNaN(date.getTime())) return '';
			return `${date.getMonth() + 1}月${date.getDate()}日 ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
		}
	}
};
</script>

<style lang="scss" scoped>
.diamond-page { min-height: 100vh; padding: 28rpx 24rpx 60rpx; box-sizing: border-box; background: #f7f8fb; }
.balance-panel { padding: 40rpx 34rpx; background: #202333; color: #fff; border-radius: 16rpx; }
.balance-label { color: #d8d9e2; font-size: 26rpx; }
.balance-row { display: flex; align-items: center; gap: 16rpx; margin: 20rpx 0 30rpx; }
.diamond-icon { width: 56rpx; height: 56rpx; flex-shrink: 0; }
.balance { font-size: 64rpx; font-weight: 700; }
.balance-actions { display: flex; gap: 18rpx; }
.recharge-button, .task-button { display: flex; align-items: center; justify-content: center; min-width: 190rpx; height: 70rpx; padding: 0 24rpx; border-radius: 8rpx; font-size: 26rpx; }
.recharge-button { background: #fff; color: #202333; font-weight: 600; }
.task-button { border: 1rpx solid rgba(255,255,255,.32); color: #fff; }
.records { margin-top: 24rpx; padding: 30rpx; background: #fff; border-radius: 16rpx; }
.section-title { display: block; margin-bottom: 12rpx; color: #202333; font-size: 30rpx; font-weight: 600; }
.record-row { display: flex; align-items: center; justify-content: space-between; min-height: 112rpx; border-top: 1rpx solid #f0edf2; }
.record-title, .record-time { display: block; }
.record-title { color: #292a32; font-size: 27rpx; }
.record-time { margin-top: 8rpx; color: #a3a0ab; font-size: 22rpx; }
.amount { color: #d4688a; font-size: 30rpx; font-weight: 600; }
.amount.spend { color: #333640; }
.empty { padding: 60rpx 0; color: #aaa6b0; text-align: center; }
.recharge-mask { position: fixed; z-index: 100; inset: 0; display: flex; align-items: flex-end; background: rgba(17,18,25,.46); }
.recharge-sheet { width: 100%; padding: 14rpx 28rpx calc(30rpx + env(safe-area-inset-bottom)); border-radius: 16rpx 16rpx 0 0; background: #fff; }
.sheet-handle { width: 72rpx; height: 7rpx; margin: 0 auto 24rpx; border-radius: 7rpx; background: #dedde4; }
.sheet-head { display: flex; align-items: flex-start; justify-content: space-between; }
.sheet-title, .sheet-subtitle { display: block; }
.sheet-title { color: #202333; font-size: 34rpx; font-weight: 700; }
.sheet-subtitle { margin-top: 8rpx; color: #92909a; font-size: 23rpx; }
.sheet-close { display: flex; align-items: center; justify-content: center; width: 56rpx; height: 56rpx; color: #777681; font-size: 40rpx; }
.vip-double { display: flex; align-items: center; justify-content: space-between; gap: 18rpx; margin-top: 24rpx; padding: 20rpx 22rpx; border: 1rpx solid #f0d4aa; border-radius: 8rpx; background: #fff8ed; }
.vip-double.active { border-color: #e8c06f; background: #fff6df; }
.vip-double-title, .vip-double-sub { display: block; }.vip-double-title { color: #7a4d22; font-size: 25rpx; font-weight: 700; }.vip-double-sub { margin-top: 6rpx; color: #a37c54; font-size: 20rpx; }
.vip-double-action, .vip-double-badge { flex-shrink: 0; color: #d4688a; font-size: 22rpx; font-weight: 700; }.vip-double-badge { color: #b7791f; font-size: 30rpx; }
.plan-scroll { width: 100%; margin-top: 30rpx; }
.plan-grid { display: inline-flex; gap: 14rpx; min-width: 100%; padding: 0 2rpx; box-sizing: border-box; }
.plan-item { position: relative; display: flex; flex: 0 0 210rpx; width: 210rpx; min-height: 190rpx; padding: 26rpx 10rpx 20rpx; align-items: center; flex-direction: column; box-sizing: border-box; border: 2rpx solid #ecebf0; border-radius: 8rpx; background: #fafafd; }
.plan-item.selected { border-color: #d4688a; background: #fff7fa; }
.recommend-badge { position: absolute; top: 0; right: 0; padding: 5rpx 12rpx; border-radius: 0 6rpx 0 6rpx; background: #d4688a; color: #fff; font-size: 18rpx; }
.double-tag { min-height: 25rpx; margin-bottom: 5rpx; color: #b7791f; font-size: 18rpx; font-weight: 700; }
.plan-diamonds { display: flex; align-items: center; gap: 8rpx; color: #202333; font-size: 34rpx; font-weight: 700; }
.plan-diamonds image { width: 38rpx; height: 38rpx; }
.plan-label { margin-top: 10rpx; color: #92909a; font-size: 21rpx; }
.base-diamonds { margin-top: 2rpx; color: #aaa2a5; font-size: 18rpx; text-decoration: line-through; }
.plan-price { margin-top: 14rpx; color: #d4688a; font-size: 28rpx; font-weight: 600; }
.pay-button { display: flex; align-items: center; justify-content: center; height: 88rpx; margin-top: 30rpx; border-radius: 8rpx; background: #202333; color: #fff; font-size: 29rpx; font-weight: 600; }
.pay-button.disabled { opacity: .48; }
.pay-note { display: block; margin-top: 18rpx; color: #a09da6; font-size: 20rpx; line-height: 1.5; text-align: center; }
</style>
